mapper.select:
select id as messageId, hospital_code as hospitalCode, tenant_id as tenantId, msg_type as msgType, payload_json as payloadJson, status as status, create_time as createTime from scm_bridge_inbox where hospital_code = #{hospitalCode} and status = '0'
and (tenant_id is null or tenant_id = '' or tenant_id = #{tenantId})
order by create_time asc limit #{limit}
